// A 2-2-1 XOR ANN that time-multiplexes ONE signed MAC across 3 neurons.
// The weights are generated by train_xor.py (not trained on FPGA).
module xor_ann_mac_core (
    input  wire clk,
    input  wire rst,
    input  wire start,
    input  wire A,
    input  wire B,
    output reg  H1,
    output reg  H2,
    output reg  Y,
    output reg  done,
    output wire busy
);
    `include "trained_weights.vh"

    localparam [3:0]
        IDLE      = 4'd0,
        LOAD_H1   = 4'd1,
        MAC_H1_A  = 4'd2,
        MAC_H1_B  = 4'd3,
        ACT_H1    = 4'd4,
        LOAD_H2   = 4'd5,
        MAC_H2_A  = 4'd6,
        MAC_H2_B  = 4'd7,
        ACT_H2    = 4'd8,
        LOAD_O    = 4'd9,
        MAC_O_H1  = 4'd10,
        MAC_O_H2  = 4'd11,
        ACT_O     = 4'd12,
        DONE      = 4'd13;

    reg [3:0] state;
    reg a_reg, b_reg;

    // Synchronize external pushbutton input to the FPGA clock.
    // For a production design, add a debouncer as well.
    reg start_meta, start_sync, start_prev;
    wire start_pulse = start_sync & ~start_prev;
    always @(posedge clk) begin
        if (rst) begin
            start_meta <= 1'b0;
            start_sync <= 1'b0;
            start_prev <= 1'b0;
        end else begin
            start_meta <= start;
            start_sync <= start_meta;
            start_prev <= start_sync;
        end
    end

    reg load_bias, mac_en;
    reg signed [7:0] bias, x, w;
    wire signed [15:0] acc;
    assign busy = (state != IDLE) && (state != DONE);

    mac_accum mac0 (
        .clk(clk), .rst(rst), .load_bias(load_bias), .mac_en(mac_en),
        .bias(bias), .x(x), .w(w), .acc(acc)
    );

    // MAC control signals and operand selection for the current neuron.
    always @(*) begin
        load_bias = 1'b0;
        mac_en = 1'b0;
        bias = 8'sd0;
        x = 8'sd0;
        w = 8'sd0;
        case (state)
            LOAD_H1:  begin load_bias = 1'b1; bias = B_H1; end
            MAC_H1_A: begin mac_en = 1'b1; x = {7'd0, a_reg}; w = W_H1_A; end
            MAC_H1_B: begin mac_en = 1'b1; x = {7'd0, b_reg}; w = W_H1_B; end
            LOAD_H2:  begin load_bias = 1'b1; bias = B_H2; end
            MAC_H2_A: begin mac_en = 1'b1; x = {7'd0, a_reg}; w = W_H2_A; end
            MAC_H2_B: begin mac_en = 1'b1; x = {7'd0, b_reg}; w = W_H2_B; end
            LOAD_O:   begin load_bias = 1'b1; bias = B_O; end
            MAC_O_H1: begin mac_en = 1'b1; x = {7'd0, H1}; w = W_O_H1; end
            MAC_O_H2: begin mac_en = 1'b1; x = {7'd0, H2}; w = W_O_H2; end
            default: ;
        endcase
    end

    // Sequencing: load bias -> 2 MAC operations -> threshold activation.
    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            a_reg <= 1'b0;
            b_reg <= 1'b0;
            H1 <= 1'b0;
            H2 <= 1'b0;
            Y <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: if (start_pulse) begin
                    a_reg <= A;
                    b_reg <= B;
                    done <= 1'b0;
                    state <= LOAD_H1;
                end
                LOAD_H1:  state <= MAC_H1_A;
                MAC_H1_A: state <= MAC_H1_B;
                MAC_H1_B: state <= ACT_H1;
                ACT_H1: begin
                    H1 <= (acc > 16'sd0);
                    state <= LOAD_H2;
                end
                LOAD_H2:  state <= MAC_H2_A;
                MAC_H2_A: state <= MAC_H2_B;
                MAC_H2_B: state <= ACT_H2;
                ACT_H2: begin
                    H2 <= (acc > 16'sd0);
                    state <= LOAD_O;
                end
                LOAD_O:   state <= MAC_O_H1;
                MAC_O_H1: state <= MAC_O_H2;
                MAC_O_H2: state <= ACT_O;
                ACT_O: begin
                    Y <= (acc > 16'sd0);
                    done <= 1'b1;
                    state <= DONE;
                end
                DONE: state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end
endmodule
